function nagEsRAM(l){ l = String(l || '').toLowerCase(); return l.indexOf('métrico') >= 0 || l.indexOf('metrico') >= 0 || l.indexOf('ram') >= 0; }
function nagRedKey(linea, cat){
  const l = String(linea || '').toLowerCase();
  if(l.indexOf('alta velocidad') >= 0) return 'av';
  if(l.indexOf('altas prestaciones') >= 0) return 'cvap';
  if(nagEsRAM(l)) return 'am_' + (cat === 'I' || cat === 'II' ? cat : '0');
  return 'cv';
}
/* distancia de frenado a parada (m). decl en ‰ (negativo = pendiente). null si no hay dato. */
function nagDistParada(linea, cat, decl, v){
  const T = NAG_DFP[nagRedKey(linea, cat)]; if(!T) return null;
  const dR = Math.max(-35, Math.min(35, Math.round(decl || 0)));
  let row = T[dR];
  if(row == null) for(let dd = dR - 1; dd >= -35; dd--){ if(T[dd] != null){ row = T[dd]; break; } }
  if(row == null) for(let dd = dR + 1; dd <= 35; dd++){ if(T[dd] != null){ row = T[dd]; break; } }
  if(row == null) return null;
  const arr = ('' + row).split(','), vMax = 30 + (arr.length - 1) * 5;
  const vq = Math.max(30, Math.min(vMax, Math.round((v || 0) / 5) * 5));
  const val = arr[(vq - 30) / 5];
  return (val === '' || val == null) ? null : +val;
}
/* curva {vel,dist} para vi = 30..viMax (paso 10) */
function nagCurvaFrenado(linea, cat, decl){
  const T = NAG_DFP[nagRedKey(linea, cat)]; if(!T) return [];
  const anyRow = T['0'] || T[Object.keys(T)[0]] || '';
  const vMax = 30 + (('' + anyRow).split(',').length - 1) * 5, out = [];
  for(let v = 30; v <= vMax; v += 10){ const d = nagDistParada(linea, cat, decl, v); if(d != null) out.push({vel:String(v), dist:String(d)}); }
  return out;
}
/* distancia de frenado de Vi hasta 160 km/h (m); null si no hay dato. Para señales preavanzadas. */
function nagDistA160(linea, cat, decl, vi){
  if(!(vi > 160) || vi > 202) return null;   /* la tabla sólo cubre Vi = 165…200 km/h */
  const T = NAG_DF160[nagRedKey(linea, cat)]; if(!T) return null;
  const dR = Math.max(-35, Math.min(35, Math.round(decl || 0)));
  let row = T[dR];
  if(row == null) for(let dd = dR - 1; dd >= -35; dd--){ if(T[dd] != null){ row = T[dd]; break; } }
  if(row == null) for(let dd = dR + 1; dd <= 35; dd++){ if(T[dd] != null){ row = T[dd]; break; } }
  if(row == null) return null;
  const arr = ('' + row).split(',');
  const vq = Math.max(165, Math.min(200, Math.round((vi || 0) / 5) * 5));
  const val = arr[(vq - 165) / 5];
  return (val === '' || val == null) ? null : +val;
}
/* distancia de proteccion frente a rebase indebido (m) para linea y declividad en ‰ (NAG apdo. 5) */
function nagRebaseIndebido(linea, decl){
  const dR = Math.max(-35, Math.min(35, Math.round(decl || 0)));
  const arr = (nagEsRAM(linea) ? NAG_RI.ram : NAG_RI.cav).split(',');
  const val = arr[35 - dR];
  return (val == null || val === '') ? null : +val;
}


