/* ================= proyectos ================= */
function nuevoProyectoModal(cb){
  const inN = el('input', {placeholder:'CATOIRA (P2)'});
  openModal('Nuevo proyecto',
    el('div', {class:'field'}, el('span', {class:'flab'}, 'Nombre del proyecto'), inN),
    () => {
      const n = inN.value.trim(); if(!n){ alert('Pon un nombre.'); return false; }
      const id = uid();
      state.proyectos.push({id, nombre:n, creado:Date.now(), pdf:'', historial:[], modo:modoActual()});
      state.proyectoActivo = id; fechaVista = null;
      registrarCambio('proyecto', 'proyecto creado');
      save();
      if(cb) cb(id); else render();
    });
}
function renombrarProyecto(id){
  const pr = state.proyectos.find(p => p.id === id); if(!pr) return;
  const inN = el('input', {value:pr.nombre});
  openModal('Renombrar proyecto',
    el('div', {class:'field'}, el('span', {class:'flab'}, 'Nombre'), inN),
    () => { const n = inN.value.trim(); if(!n) return false; const viejo = pr.nombre; pr.nombre = n;
      registrarCambio('proyecto', 'renombrado de "' + viejo + '" a "' + n + '"'); save(); render(); });
}
function borrarProyecto(id){
  const pr = state.proyectos.find(p => p.id === id); if(!pr) return;
  const n = state.elementos.filter(e => e.proyectoId === id).length;
  if(!confirm('Se borrará el proyecto "' + pr.nombre + '"' + (n ? ' y sus ' + n + ' elemento(s)' : '') + '. ¿Continuar?')) return;
  state.proyectos = state.proyectos.filter(p => p.id !== id);
  state.elementos = state.elementos.filter(e => e.proyectoId !== id);
  if(state.proyectoActivo === id) state.proyectoActivo = null;
  asegurarProyectoModo();
  save(); render();
}

/* ================= modo Diseño de obra (NAS 811) ================= */
/* NAS 818 §1 y §4: tipos de bloqueo. El sufijo dice la topología de la línea —
   U = vía única · D = vía doble · B = vía doble banalizada. */
const DZ_BLOQUEOS = ['BAU', 'BAD', 'BAB', 'BLAU', 'BLAD', 'BLAB', 'BCA', 'BSL'];
/* NAG 0-3-1.0: obra de canalización que se genera junto a la señalización */
const DZ_CANALIZ = ['No generar', 'Sólo cruces bajo vía', 'Arquetas y canalización', 'Completa (+ hitos)'];
const DZCOLS = {
  vias:[
    {k:'est',   t:'Estación',            ph:'CATOIRA'},
    {k:'num',   t:'Nº vía',              ph:'1'},
    {k:'pkIni', t:'PK inicio',           ph:'18+400'},
    {k:'pkFin', t:'PK fin',              ph:'25+900'},
    {k:'tipo',  t:'Tipo',               o:['general','apartado','topera','banalizada']},
    {k:'vmax',  t:'Vel. máx (km/h)',     ph:'160'},
    {k:'sentido', t:'Sentido de circulación', o:['Ambos (banalizada)','PK creciente','PK decreciente']},
    {k:'parada', t:'Parada comercial',  o:['Sí','No']}
  ],
  agujas:[
    {k:'est',       t:'Estación',            ph:'CATOIRA'},
    {k:'nombre',    t:'Nombre',                ph:'1'},
    {k:'pkJCA',     t:'PK punta (JCA)',        ph:'19+050'},
    {k:'pkPiq',     t:'PK piquete vía libre',  ph:'19+068'},
    {k:'viaOrig',   t:'Vía origen',            ph:'1'},
    {k:'viaDest',   t:'Vía destino',           ph:'3'},
    {k:'vDir',      t:'Vel. directa',          ph:'160'},
    {k:'vDesv',     t:'Vel. desviada',         ph:'30'},
    {k:'entraPor',  t:'Se entra por',         o:['punta (PK creciente)','talón (PK creciente)','punta (PK decreciente)','talón (PK decreciente)']},
    {k:'escapeCon', t:'Forma escape con',      ph:'3'}
  ],
  piquetes:[
    {k:'est',    t:'Estación', ph:'CATOIRA'},
    {k:'nombre', t:'Nombre', ph:'P-1'},
    {k:'pk',     t:'PK',     ph:'19+068'},
    {k:'viaA',   t:'Vía A',  ph:'1'},
    {k:'viaB',   t:'Vía B',  ph:'3'}
  ],
  estaciones:[
    {k:'nombre', t:'Nombre',    ph:'CATOIRA'},
    {k:'pkIni',  t:'PK inicio', ph:'19+000'},
    {k:'pkFin',  t:'PK fin',    ph:'19+600'}
  ],
  existentes:[
    {k:'est',     t:'Estación',  ph:'VILAGARCIA'},
    {k:'codigo',  t:'Código',    ph:"E'5"},
    {k:'pk',      t:'PK',        ph:'1+963'},
    {k:'tipo',    t:'Tipo',     o:['Entrada','Avanzada','Preavanzada','Salida','Retroceso','Intermedia','Liberación','Indicadora de salida','Indicadora de aguja']},
    {k:'via',     t:'Vía',       ph:'1'},
    {k:'sentido', t:'Sentido que protege', o:['PK creciente','PK decreciente']}
  ],
  pasos:[
    {k:'nombre', t:'Nombre',            ph:'Cº de Trabanca'},
    {k:'pk',     t:'PK',                ph:'1+424'},
    {k:'tipo',   t:'Tipo',             o:['SLA','SBA','SBE','Automático','Manual']},
    {k:'vias',   t:'Vías que cruza',    ph:'1,3'},
    {k:'aviso',  t:'Distancia de aviso (m)', ph:'1800'}
  ]
};
/* Curva de distancia de frenado ORIENTATIVA (conducción manual, freno de servicio, Red Convencional,
   pendiente ~0). Anclada al ejemplo A5.4 de la NAS 840 (1096 m a 100 km/h, λ 78 %) con el modelo
   d(v)=v·tc+v²/(2a), tc=4 s, a≈0,39 m/s². Los valores reales están en la NAG 0-8-5.0 «Distancia de
   Frenado y Señales» y dependen del tipo de línea, λ y gradiente: el usuario debe sustituirlos. */
const DZ_FRENADO_DEF = [
  {vel:'60', dist:'420'}, {vel:'80', dist:'630'}, {vel:'100', dist:'1096'}, {vel:'120', dist:'1550'},
  {vel:'140', dist:'2085'}, {vel:'160', dist:'2700'}, {vel:'200', dist:'4160'}, {vel:'250', dist:'6430'}, {vel:'300', dist:'9200'}
];
function disenoDe(){
  const pr = proyActivo();
  if(!pr) return {vias:[], agujas:[], piquetes:[], estaciones:[], generados:[], parametros:{}};
  if(!pr.diseno || typeof pr.diseno !== 'object') pr.diseno = {};
  const d = pr.diseno;
  ['vias','agujas','piquetes','estaciones','pasos','existentes','generados'].forEach(k => { if(!Array.isArray(d[k])) d[k] = []; });
  d.generados.forEach(g => { if(!g.id) g.id = uid(); });
  if(!d.parametros || typeof d.parametros !== 'object') d.parametros = {linea:'Convencional', bloqueo:'BAU', sistemas:'ASFA + ERTMS N2', gradiente:'', catAM:'', vmax:'', cantones:'', distFrenado:[]};
  if(!Array.isArray(d.parametros.distFrenado)) d.parametros.distFrenado = [];
  if(d.parametros.cantones == null) d.parametros.cantones = '';
  if(d.parametros.canaliz == null) d.parametros.canaliz = 'No generar';
  if(d.parametros.vmax == null) d.parametros.vmax = '';
  if(d.parametros.catAM == null) d.parametros.catAM = '';
  if(/^RAM$/i.test(d.parametros.linea || '')) d.parametros.linea = 'Ancho Métrico';
  return d;
}

