/* mapa Diseño → Seguimiento: tipo generado → [tipoId de seguimiento, valor de «Tipo de señal»,
   valores fijos que además se rellenan] */
const DZ_MAPA_SEG = {
  'Señal de entrada':['t_senal', 'Entrada'], 'Señal de salida':['t_senal', 'Salida'],
  'Señal avanzada':['t_senal', 'Avanzada'], 'Señal preavanzada':['t_senal', 'Preavanzada'],
  'Señal de retroceso':['t_senal', 'Retroceso'], 'Señal de liberación':['t_senal', 'Liberación'],
  'Señal intermedia':['t_senal', 'Intermedia'], 'Señal de PCA':['t_senal', 'PCA'],
  'Pantalla ERTMS N2':['t_senal', 'Pantalla ERTMS N2'],
  'Indicadora de posición de aguja':['t_senal', 'Indicadora de aguja'],
  'Indicadora de salida':['t_senal', 'Indicadora de salida'], 'Circuito de vía':['t_cdv', null],
  'Baliza':['t_bal', null], 'Baliza infill':['t_bal', null], 'Punto negro':['t_hito', null], 'Topera':['t_hito', null],
  'Paso a nivel':['t_hito', null], 'Pedal de paso a nivel':['t_hito', null],
  'Arqueta':['t_arq', null], 'Canalización':['t_canal', null],
  'Cruce bajo vía':['t_canal', null, {f_tcanal:'Cruce bajo vía', f_lado:'Cruce bajo vía'}],
  'Hito de zanja':['t_hito', null]
};
/* copia la geometría del diseño (estaciones → lugares, vías → vías del esquema) al proyecto de seguimiento.
   Sin esto las vías «no coinciden»: el esquema no sabe dónde empieza y acaba cada vía ni de qué estación es. */
function dzGeometriaASeguimiento(d, pr){
  pr.lugares = pr.lugares || []; pr.vias = pr.vias || [];
  let nL = 0, nV = 0;
  (d.estaciones || []).forEach(s => {
    const nom = String(s.nombre || '').trim(), a = pkNum(s.pkIni), b = pkNum(s.pkFin);
    if(!nom || !isFinite(a) || !isFinite(b)) return;
    const ya = pr.lugares.find(l => String(l.nombre || '').toLowerCase() === nom.toLowerCase());
    if(ya){ ya.pkIni = Math.min(a, b); ya.pkFin = Math.max(a, b); }
    else { pr.lugares.push({id:uid(), nombre:nom, pkIni:Math.min(a, b), pkFin:Math.max(a, b)}); nL++; }
  });
  const lugId = nom => (pr.lugares.find(l => String(l.nombre || '').toLowerCase() === String(nom || '').trim().toLowerCase()) || {}).id || 'general';
  const esGen = v => /general|banaliz/i.test(v.tipo || '');
  const genNum = String(((d.vias || []).find(esGen) || {}).num || '1').trim();
  /* De qué vía sale cada vía y por dónde se conecta lo dicen las AGUJAS (viaOrig → viaDest).
     Sin esto todas colgaban de la general y las toperas salían por el extremo contrario. */
  const ags = (d.agujas || []).map(a => ({est:String(a.est || '').trim(), o:String(a.viaOrig || '').trim(),
    dst:String(a.viaDest || '').trim(), jca:pkNum(a.pkJCA), piq:pkNum(a.pkPiq)}));
  (d.vias || []).forEach(v => {
    const num = String(v.num || '').trim(), est = String(v.est || '').trim();
    if(!num || num === genNum) return;   /* la vía general de línea es la línea base del esquema */
    const a = pkNum(v.pkIni), b = pkNum(v.pkFin);
    if(!isFinite(a) || !isFinite(b)) return;
    /* las demás vías generales (vía 2 de una línea doble) recorren toda la línea: sin lugar */
    const lug = esGen(v) ? 'general' : lugId(est);
    const lo = Math.min(a, b), hi = Math.max(a, b), topera = /topera/i.test(v.tipo || '');
    /* la aguja que da acceso a esta vía: la de la misma estación cuya punta cae más cerca */
    const pto = x => isFinite(x.piq) ? x.piq : x.jca;
    const acc = ags.filter(x => x.dst === num && x.o && x.o !== num && (!est || !x.est || x.est === est) && isFinite(pto(x)))
      .sort((x, y) => Math.min(Math.abs(pto(x) - lo), Math.abs(pto(x) - hi)) - Math.min(Math.abs(pto(y) - lo), Math.abs(pto(y) - hi)))[0];
    const padre = (acc && acc.o) || genNum;
    /* extremo conectado de una topera: el más cercano a la aguja; si no hay aguja, el PK inicio
       declarado — la plantilla se rellena desde la conexión hacia el fondo de saco */
    let ladoCon = 'ini';
    if(topera){
      const cp = acc ? pto(acc) : a;
      ladoCon = Math.abs(cp - lo) <= Math.abs(cp - hi) ? 'ini' : 'fin';
    }
    const rec = {num, padre, lugar:lug, tipo:topera ? 'topera' : 'secundaria', pkIni:lo, pkFin:hi, ladoCon};
    const ya = pr.vias.find(x => String(x.num) === num && (x.lugar || 'general') === lug);
    if(ya) Object.assign(ya, rec); else { pr.vias.push(Object.assign({id:uid()}, rec)); nV++; }
  });
  return {lugares:nL, vias:nV};
}
/* Agujas y piquetes de la geometría de entrada, como elementos de seguimiento. */
function dzExtraGeometria(d){
  const extra = [];
  (d.agujas || []).forEach(a => {
    const pk = pkNum(a.pkJCA); if(!isFinite(pk)) return;
    extra.push({_tipo:'t_aguja', codigo:'AG ' + String(a.nombre || '').trim(), pk:toPkStr(pk),
      via:String(a.viaOrig || '').trim(), est:String(a.est || '').trim(),
      criterio:'Geometría de diseño: JCA en PK ' + toPkStr(pk) + (a.pkPiq ? ', piquete en ' + a.pkPiq : '')
        + (a.viaDest ? ' · vía ' + a.viaOrig + '→' + a.viaDest : '')
        + (a.vDir || a.vDesv ? ' · V directa ' + (a.vDir || '—') + ' / desviada ' + (a.vDesv || '—') + ' km/h' : '')
        + (a.entraPor ? ' · se entra por ' + a.entraPor : '')});
  });
  (d.piquetes || []).forEach(p => {
    const pk = pkNum(p.pk); if(!isFinite(pk)) return;
    /* si el piquete no dice su vía, se toma la de la aguja del mismo nombre: si no, en el esquema
       de seguimiento se queda en la vía general */
    const ag = (d.agujas || []).find(a => String(a.nombre || '').trim() === String(p.nombre || '').trim()
      && String(a.est || '').trim() === String(p.est || '').trim());
    extra.push({_tipo:'t_piq', codigo:String(p.nombre || '').trim() || ('PIQ ' + toPkStr(pk)), pk:toPkStr(pk),
      via:String(p.viaA || '').trim() || String((ag || {}).viaOrig || '').trim(), est:String(p.est || '').trim(),
      criterio:'Geometría de diseño: piquete de entrevías entre la vía ' + (p.viaA || (ag || {}).viaOrig || '—') + ' y la vía ' + (p.viaB || (ag || {}).viaDest || '—')});
  });
  return extra;
}
/* Traduce un elemento generado al tipo y los campos de Seguimiento. Lo usan el envío directo y la
   exportación a Excel, para que las dos rutas produzcan exactamente lo mismo. */
function dzValoresSeg(g, d){
  const m = g._tipo ? [g._tipo, null] : DZ_MAPA_SEG[g.tipo];
  if(!m) return null;
  const val = {};
  if(g.pk) val.f_pk = g.pk;
  if(g.pkIni) val.f_pkini = g.pkIni;
  if(g.pkFin) val.f_pkfin = g.pkFin;
  /* un elemento puntual que va a parar a un tipo lineal (el cruce bajo vía es una canalización
     transversal) sólo tiene UN PK, el del cruce: se rellena el de inicio y se deja vacío el final */
  const tp = getTipo(m[0]);
  if(g.pk && !g.pkIni && tp && tp.campos.some(r => r.campoId === 'f_pkini')) val.f_pkini = g.pk;
  if(g.via) val.f_via = String(g.via);
  if(g.est) val.f_est = g.est;
  if(m[1]) val.f_tsenal = m[1];
  if(g.senal) val.f_senasoc = g.senal;
  if(g.lado) val.f_lado = g.lado;
  if(m[2]) Object.assign(val, m[2]);
  if(m[0] === 't_bal' && g.senal && d){
    const pg = pkNum(g.pk), ps = pkNum(((d.generados || []).find(x => x.codigo === g.senal) || {}).pk);
    if(isFinite(pg) && isFinite(ps)) val.f_distsen = String(Math.round(Math.abs(pg - ps) * 1000));
  }
  val.f_obs = (g.criterio || '') + (g.revisar ? ' [REVISAR]' : '');
  return {tipoId:m[0], codigo:g.codigo, valores:val, tipo:tp};
}
function dzEnviarASeguimiento(){
  const d = disenoDe();
  if(!(d.generados || []).length){ alert('No hay elementos generados.'); return; }
  const srcId = (proyActivo() || {}).id;
  const segs = proyectosDelModo('seguimiento');
  const sel = el('select', null,
    ...segs.map(p => el('option', {value:p.id}, p.nombre)),
    el('option', {value:'__nuevo'}, '➕ Nuevo proyecto de seguimiento'));
  const inN = el('input', {placeholder:'Nombre del nuevo proyecto', style:'margin-top:8px;display:' + (segs.length ? 'none' : 'block')});
  if(!segs.length) sel.value = '__nuevo';
  sel.addEventListener('change', () => { inN.style.display = sel.value === '__nuevo' ? 'block' : 'none'; });
  const selDup = el('select', null,
    el('option', {value:'act'}, 'Actualizar los que ya existan (por código) y añadir los nuevos'),
    el('option', {value:'add'}, 'Añadir siempre (puede dejar duplicados)'),
    el('option', {value:'reset'}, 'Borrar los importados antes de este diseño y volver a crearlos'));
  const chkGeo = el('input', {type:'checkbox', checked:'checked'});
  const chkAg = el('input', {type:'checkbox', checked:'checked'});
  openModal('Enviar a seguimiento',
    el('div', null,
      el('div', {class:'field'}, el('span', {class:'flab'}, 'Proyecto de seguimiento destino'), sel, inN),
      el('div', {class:'field'}, el('span', {class:'flab'}, 'Si ya se había importado antes'), selDup),
      el('label', {style:'display:flex;gap:8px;align-items:center;margin-top:8px;font-size:13px'}, chkGeo,
        'Llevar también la geometría: estaciones → lugares y vías → vías del esquema'),
      el('label', {style:'display:flex;gap:8px;align-items:center;margin-top:6px;font-size:13px'}, chkAg,
        'Llevar también las agujas y los piquetes como elementos de seguimiento'),
      el('p', {class:'hint'}, 'La estación de cada elemento se guarda en el campo «Estación» y como «lugar», para que dos vías con el mismo número en estaciones distintas no se mezclen.')),
    () => {
      let pid = sel.value;
      if(pid === '__nuevo'){
        const nm = inN.value.trim() || ('Obra ' + (proyActivo().nombre || ''));
        pid = uid();
        state.proyectos.push({id:pid, nombre:nm, creado:Date.now(), pdf:'', historial:[], modo:'seguimiento', vias:[], lugares:[], andenes:[]});
      }
      const pr = state.proyectos.find(p => p.id === pid);
      const modoDup = selDup.value;
      let nBorr = 0;
      if(modoDup === 'reset'){
        const antes = state.elementos.length;
        state.elementos = state.elementos.filter(e => !(e.proyectoId === pid && e.origenDiseno === srcId));
        nBorr = antes - state.elementos.length;
      }
      const geo = chkGeo.checked ? dzGeometriaASeguimiento(d, pr) : {lugares:0, vias:0};
      /* la geometría de entrada (agujas y piquetes) también es obra a seguir: se manda como elementos */
      const extra = chkAg.checked ? dzExtraGeometria(d) : [];
      let nNuevo = 0, nAct = 0;
      let nExist = 0;
      d.generados.concat(extra).forEach(g => {
        if(g.existente){ nExist++; return; }   /* ya montada: no es obra nueva */
        const r = dzValoresSeg(g, d); if(!r) return;
        const m = [r.tipoId], val = r.valores;
        /* el código sólo es único DENTRO de una estación (hay una S1/1 en cada una):
           la estación forma parte de la identidad, si no se pisan entre ellas */
        const prev = modoDup === 'act'
          ? state.elementos.find(e => e.proyectoId === pid && !e.borrado && e.tipoId === m[0]
              && (e.codigo || '') === (g.codigo || '') && (e.valores.f_est || '') === (g.est || ''))
          : null;
        if(prev){
          prev.hist = prev.hist || [];
          prev.hist.push({ts:Date.now(), snap:{codigo:prev.codigo, valores:clone(prev.valores), plano:prev.plano ? clone(prev.plano) : null}});
          if(prev.hist.length > 40) prev.hist.shift();
          Object.assign(prev.valores, val);                    /* respeta estado, fotos y lo demás */
          prev.origenDiseno = srcId; prev.modificado = Date.now();
          nAct++;
        } else {
          const tp = getTipo(m[0]);
          /* «Estado de montaje» es obligatorio: sin él el elemento nace incompleto y falsea los KPI */
          if(tp && tp.campos.some(r => r.campoId === 'f_estado')) val.f_estado = 'Pendiente';
          state.elementos.push({id:uid(), proyectoId:pid, tipoId:m[0], codigo:g.codigo, valores:val, hist:[],
            plano:null, origenDiseno:srcId, creado:Date.now(), modificado:Date.now()});
          nNuevo++;
        }
      });
      state.modo = 'seguimiento'; state.proyectoActivo = pid; currentView = 'bd';
      registrarCambio('alta (diseño)', nNuevo + ' altas y ' + nAct + ' actualizaciones desde Diseño de obra');
      save(); render();
      alert('Enviado a "' + (pr || {}).nombre + '":\n· ' + nNuevo + ' elementos nuevos\n· ' + nAct + ' actualizados'
        + (nExist ? '\n· ' + nExist + ' omitidos por estar declarados como ya existentes' : '')
        + (nBorr ? '\n· ' + nBorr + ' borrados de la importación anterior' : '')
        + (geo.lugares || geo.vias ? '\n· ' + geo.lugares + ' lugares y ' + geo.vias + ' vías creadas en el esquema' : ''));
    });
}
