  const num = s => pkNum(s), pks = [];
  (d.vias || []).forEach(v => { pks.push(num(v.pkIni), num(v.pkFin)); });
  (d.agujas || []).forEach(a => pks.push(num(a.pkJCA)));
  (d.piquetes || []).forEach(p => pks.push(num(p.pk)));
  (d.estaciones || []).forEach(s => { pks.push(num(s.pkIni), num(s.pkFin)); });
  (d.generados || []).forEach(g => { pks.push(num(g.pk), num(g.pkIni), num(g.pkFin)); });
  const vals = pks.filter(x => !isNaN(x));
  if(vals.length < 2){ c.appendChild(el('p', {class:'hint'}, 'Introduce las vías (PK inicio/fin) en «Datos de entrada» para ver el esquema.')); return c; }
