let esqZoom = null, esqAdd = {on:false, tipoId:null}, esqCtx = {};
let esqModo = null, esqPage = 1, esqPdfScale = null, esqColocar = null, esqPageLock = false;
let esqCalib = false, esqSubpaths = null, esqSubPage = 0, detSimb = null;
