/* ancla de la vista del Esquema por PK: se guarda el PK que hay en el borde izquierdo (no los píxeles),
   así la posición sobrevive a un re-render aunque cambien el zoom, el ancho o los filtros. */
let esqAncla = null;
function esqSoltarAncla(){ esqAncla = null; esqWheelPend = null; }
/* zoom desde los botones manteniendo el centro de lo que se está mirando */
function esqZoomBtn(f){
  const box = /** @type {HTMLElement | null} */ (document.querySelector('.esq-wrap'));
  if(box && esqCtx.pxKm && box.dataset.ok === '1'){
    const cx = box.clientWidth / 2;
    esqWheelPend = {pkU:esqCtx.mn + (box.scrollLeft + cx - esqCtx.mL) / esqCtx.pxKm, cx, top:box.scrollTop};
  }
  esqZoom = Math.max(20, Math.min(20000, (esqZoom || esqFit || 100) * f));
  render();
}
let _rrRAF = 0, _rlT = 0;
function reRenderPronto(){ cancelAnimationFrame(_rrRAF); _rrRAF = requestAnimationFrame(render); }
function reRenderLento(){ clearTimeout(_rlT); _rlT = setTimeout(render, 130); }
function viasConocidas(){
  const s = new Set();
  (proyActivo().vias || []).forEach(v => { if(v.num != null && v.num !== '') s.add(String(v.num)); });
  elementosProy().forEach(e => {
    const v = String(viaDe(e) || '').trim();
    if(v && v !== '—' && !/^1(\D|$)/.test(v)) s.add(v);
  });
  return [...s].sort((a, b) => String(a).localeCompare(String(b), 'es', {numeric:true}));
}
/* vías que el programa dibuja a partir del campo Vía de los elementos (no están en proyecto.vias) */
function viasDetectadas(){
  const dibujadas = new Set((proyActivo().vias || []).map(v => String(v.num)));
  const m = new Map();
  elementosProy().forEach(e => {
    const v = String(viaDe(e) || '').trim();
    if(!v || v === '—' || /^1(\D|$)/.test(v) || dibujadas.has(v)) return;
    m.set(v, (m.get(v) || 0) + 1);
  });
  return [...m.entries()].map(([num, n]) => ({num, n})).sort((a, b) => String(a.num).localeCompare(String(b.num), 'es', {numeric:true}));
}
/* convierte una vía detectada en vía editable de proyecto.vias (PKs desde los elementos) */
function materializarVia(num){
  const pr = proyActivo(); pr.vias = pr.vias || [];
  const ya = pr.vias.find(v => String(v.num) === String(num));
  if(ya) return ya;
  const pks = [];
  elementosProy().forEach(e => {
    if(String(viaDe(e) || '').trim() !== String(num)) return;
    const p = elemPK(e); [p.ini, p.fin, p.pu].forEach(k => { if(!isNaN(k)) pks.push(k); });
  });
  pks.sort((a, b) => a - b);
  const a = pks.length ? pks[0] : mnPKProy(), b = pks.length ? pks[pks.length - 1] : a + 0.3;
  const sp = Math.max((b - a) * 0.15, 0.03);
  const rec = {id:uid(), num:String(num), padre:'1', lugar:'general', tipo:'secundaria', pkIni:a - sp, pkFin:b + sp};
  pr.vias.push(rec); registrarCambio('vía', 'vía ' + num + ' detectada → editable'); save();
  return rec;
}
function mnPKProy(){ const p = []; elementosProy().forEach(e => { const q = elemPK(e); [q.ini, q.fin, q.pu].forEach(k => { if(!isNaN(k)) p.push(k); }); }); return p.length ? Math.min(...p) : 0; }
/* borra el valor del campo Vía = num en los elementos que lo tengan (con snapshot en histórico) */
function quitarViaDeElementos(num){
  let n = 0;
  state.elementos.forEach(e => {
    if(e.proyectoId !== state.proyectoActivo || e.borrado) return;
    const t = getTipo(e.tipoId); if(!t) return;
    const vr = viaRefDe(t); if(!vr) return;
    if(String(e.valores[vr] || '').trim() !== String(num)) return;
    e.hist = e.hist || [];
    e.hist.push({ts:Date.now(), snap:{codigo:e.codigo, valores:clone(e.valores), plano:e.plano ? clone(e.plano) : null}});
    if(e.hist.length > 40) e.hist.shift();
    e.valores[vr] = ''; e.modificado = Date.now(); n++;
  });
  if(n){ registrarCambio('vía', 'vía ' + num + ' quitada de ' + n + ' elemento(s)'); save(); }
  return n;
}
function nuevaViaModal(existing, pk1, pk2){
  const pr = proyActivo(); pr.vias = pr.vias || [];
  const esEdit = !!existing;
  const inNum = el('input', {value:esEdit ? existing.num : '', placeholder:'3'});
  const tipoInicial = esEdit ? existing.tipo : 'secundaria';
  const selTipo = el('select', null,
    el('option', {value:'secundaria', ...(tipoInicial !== 'topera' ? {selected:'selected'} : {})}, 'Secundaria (sale y vuelve)'),
    el('option', {value:'topera', ...(tipoInicial === 'topera' ? {selected:'selected'} : {})}, 'Topera (sin retorno)'));

  const conocidas = viasConocidas().filter(n => !esEdit || n !== String(existing.num));
  const padreInicial = esEdit ? String(existing.padre) : '';
  const padreEsGeneral = padreInicial === '' || padreInicial === '1';
  const padreEsConocida = padreEsGeneral || conocidas.includes(padreInicial);
  const selPad = el('select', null,
    el('option', {value:'', ...(padreEsGeneral ? {selected:'selected'} : {})}, 'Vía general (1)'),
    ...conocidas.map(n => el('option', {value:n, ...(n === padreInicial ? {selected:'selected'} : {})}, 'Vía ' + n)),
    el('option', {value:'__otra', ...(!padreEsConocida ? {selected:'selected'} : {})}, 'Otra vía…'));
  const inPadOtra = el('input', {value:!padreEsConocida ? padreInicial : '', placeholder:'nº de vía', style:(padreEsConocida ? 'display:none;' : '') + 'margin-top:6px'});
  selPad.addEventListener('change', () => { inPadOtra.style.display = selPad.value === '__otra' ? '' : 'none'; });

  const lugs = pr.lugares || [];
  const lugSel = esEdit ? (existing.lugar || 'general') : 'general';
  const selLugar = el('select', null,
    el('option', {value:'general', ...(lugSel === 'general' ? {selected:'selected'} : {})}, 'GENERAL (sin lugar concreto)'),
    ...lugs.map(l => el('option', {value:l.id, ...(l.id === lugSel ? {selected:'selected'} : {})}, l.nombre)));

  let valA = null, valB = null, valCon = null, valLong = '';
  if(esEdit){
    valA = existing.pkIni; valB = existing.pkFin;
    if(existing.tipo === 'topera'){
      valCon = existing.ladoCon === 'fin' ? existing.pkFin : existing.pkIni;
      const otro = existing.ladoCon === 'fin' ? existing.pkIni : existing.pkFin;
      valLong = String(Math.round((otro - valCon) * 1000));
    }
  } else {
    valA = pk1 != null ? pk1 : null; valB = pk2 != null ? pk2 : null;
    valCon = pk1 != null ? pk1 : null;
    valLong = (pk1 != null && pk2 != null) ? String(Math.round((pk2 - pk1) * 1000)) : '';
  }
  const inA = el('input', {value:valA != null ? toPkStr(valA) : '', placeholder:'19+050'});
  const inB = el('input', {value:valB != null ? toPkStr(valB) : '', placeholder:'19+300'});
  const inCon = el('input', {value:valCon != null ? toPkStr(valCon) : '', placeholder:'19+050'});
  const inLong = el('input', {value:valLong, placeholder:'+200 ó -200'});
  const esTop = tipoInicial === 'topera';
  const grpSec = el('div', {class:'cols2', style:esTop ? 'display:none' : ''},
    el('div', {class:'field'}, el('span', {class:'flab'}, 'PK inicio (punto de salida)'), inA),
    el('div', {class:'field'}, el('span', {class:'flab'}, 'PK fin (punto de retorno)'), inB));
  const grpTop = el('div', {class:'cols2', style:esTop ? '' : 'display:none'},
    el('div', {class:'field'}, el('span', {class:'flab'}, 'PK de conexión'), inCon),
    el('div', {class:'field'}, el('span', {class:'flab'}, 'Longitud (m) con signo'), inLong));
  selTipo.addEventListener('change', () => {
    const top = selTipo.value === 'topera';
    grpSec.style.display = top ? 'none' : ''; grpTop.style.display = top ? '' : 'none';
  });

  openModal(esEdit ? 'Editar vía' : 'Nueva vía',
    el('div', null,
      el('div', {class:'cols2'},
        el('div', {class:'field'}, el('span', {class:'flab'}, 'Número de vía'), inNum),
        el('div', {class:'field'}, el('span', {class:'flab'}, 'Tipo de vía'), selTipo)),
      el('div', {class:'field'}, el('span', {class:'flab'}, 'Sale de'), selPad, inPadOtra),
      el('div', {class:'field'}, el('span', {class:'flab'}, 'Lugar al que pertenece'), selLugar),
      grpSec, grpTop,
      el('p', {class:'hint', style:'margin-top:0'}, 'Topera: longitud +200 = hacia PK creciente (derecha); −200 = hacia PK decreciente (izquierda).')
    ),
    () => {
      const num = inNum.value.trim(); if(!num){ alert('Pon el número de vía.'); return false; }
      const padre = selPad.value === '__otra' ? (inPadOtra.value.trim() || '1') : (selPad.value || '1');
      const lugar = selLugar.value || 'general';
      let rec;
      if(selTipo.value === 'topera'){
        const con = pkNum(inCon.value), L = parseFloat(String(inLong.value).replace(',', '.'));
        if(isNaN(con) || !isFinite(L) || L === 0){ alert('Pon el PK de conexión y una longitud (m) distinta de 0.'); return false; }
        const end = con + L / 1000;
        rec = {num, padre, lugar, tipo:'topera', pkIni:Math.min(con, end), pkFin:Math.max(con, end), ladoCon:L >= 0 ? 'ini' : 'fin'};
      } else {
        const a = pkNum(inA.value), b = pkNum(inB.value);
        if(isNaN(a) || isNaN(b)){ alert('Pon PK inicio y fin válidos.'); return false; }
        rec = {num, padre, lugar, tipo:'secundaria', pkIni:Math.min(a, b), pkFin:Math.max(a, b)};
      }
      if(esEdit){ Object.assign(existing, rec); registrarCambio('vía', 'editada vía ' + num); }
      else { pr.vias.push(Object.assign({id:uid()}, rec)); registrarCambio('vía', 'añadida vía ' + num + ' desde vía ' + padre); }
      esqDibVia = false; esqDibP = null; save(); render();
    },
    esEdit ? () => {
      pr.vias = pr.vias.filter(x => x.id !== existing.id);
      registrarCambio('vía', 'borrada vía ' + existing.num);
      save(); render();
      quitarPreguntaViaElementos(existing.num);
    } : null
  );
}
/* al borrar una vía, ofrece quitarla también del campo Vía de los elementos que la usan */
function quitarPreguntaViaElementos(num){
  const cnt = elementosProy().filter(e => String(viaDe(e) || '').trim() === String(num)).length;
  if(cnt && confirm(cnt + ' elemento(s) tienen la vía ' + num + '. ¿Quitarles también ese valor? (si no, la vía volverá a dibujarse como "detectada")')){
    quitarViaDeElementos(num); render();
    return true;
  }
  return false;
}
function configVias(){
  const pr = proyActivo();
  const det = viasDetectadas();
  openModal('Vías',
    el('div', null,
      el('span', {class:'flab'}, 'Dibujadas manualmente'),
      (pr.vias || []).length ? el('div', {class:'list'}, ...pr.vias.map(v => el('div', {class:'row pick', onclick:() => { closeModal(); nuevaViaModal(v); }},
        el('span', {class:'grow'}, 'Vía ' + v.num + '  ', el('span', {style:'color:var(--tx3)'},
          '· ' + (v.tipo === 'topera' ? 'topera' : 'secundaria') + ' desde vía ' + v.padre +
          ' · ' + (v.lugar && v.lugar !== 'general' ? ((pr.lugares || []).find(l => l.id === v.lugar) || {}).nombre || 'lugar' : 'GENERAL') +
          ' · ' + toPkStr(v.pkIni) + '–' + toPkStr(v.pkFin))),
        el('button', {class:'btn icon sm danger', onclick:ev => { ev.stopPropagation(); pr.vias = pr.vias.filter(x => x.id !== v.id); registrarCambio('vía', 'borrada vía ' + v.num); save(); closeModal(); quitarPreguntaViaElementos(v.num); configVias(); }}, '✕')
      ))) : el('div', {class:'empty'}, 'Ninguna vía dibujada.'),
      det.length ? el('div', {style:'margin-top:14px'},
        el('span', {class:'flab'}, 'Detectadas al importar (a partir del campo Vía de los elementos)'),
        el('div', {class:'list'}, ...det.map(d => el('div', {class:'row pick', onclick:() => { closeModal(); const v = materializarVia(d.num); nuevaViaModal(v); }},
          el('span', {class:'grow'}, 'Vía ' + d.num + '  ', el('span', {style:'color:var(--tx3)'}, '· ' + d.n + ' elemento(s) · sin dibujar')),
          el('button', {class:'btn sm', onclick:ev => { ev.stopPropagation(); closeModal(); const v = materializarVia(d.num); nuevaViaModal(v); }}, 'Editar'),
          el('button', {class:'btn icon sm danger', title:'Quitar esta vía de los elementos', onclick:ev => {
            ev.stopPropagation();
            if(confirm('¿Quitar la vía ' + d.num + ' de ' + d.n + ' elemento(s)? Se borrará el valor del campo Vía en esos elementos (queda en el histórico).')){
              quitarViaDeElementos(d.num); save(); closeModal(); configVias();
            }
          }}, '✕')
        )))
      ) : null,
      el('div', {style:'margin-top:12px'}, el('button', {class:'btn sm', onclick:() => { closeModal(); nuevaViaModal(null); }}, '+ Nueva vía')),
      el('p', {class:'hint'}, 'Clic en una vía dibujada para editarla o borrarla. Una vía "detectada" se crea sola desde el campo Vía de los elementos: pulsa "Editar" para poder ajustar su número y PKs, o ✕ para quitarla.')
    ), null);
}
function nuevoLugarModal(existing){
  const pr = proyActivo(); pr.lugares = pr.lugares || [];
  const inNom = el('input', {value:existing ? existing.nombre : '', placeholder:'CATOIRA (P2)'});
  const inA = el('input', {value:existing ? toPkStr(existing.pkIni) : '', placeholder:'8+900'});
  const inB = el('input', {value:existing ? toPkStr(existing.pkFin) : '', placeholder:'9+900'});
  openModal(existing ? 'Editar lugar' : 'Nuevo lugar',
    el('div', null,
      el('div', {class:'field'}, el('span', {class:'flab'}, 'Nombre'), inNom),
      el('div', {class:'cols2'},
        el('div', {class:'field'}, el('span', {class:'flab'}, 'PK inicio'), inA),
        el('div', {class:'field'}, el('span', {class:'flab'}, 'PK fin'), inB)),
      el('p', {class:'hint', style:'margin-top:0'}, 'Cualquier elemento cuyo PK caiga entre estos dos valores se considera de este lugar.')
    ),
    () => {
      const nom = inNom.value.trim(); if(!nom){ alert('Pon un nombre.'); return false; }
      const a = pkNum(inA.value), b = pkNum(inB.value);
      if(isNaN(a) || isNaN(b)){ alert('Pon PK inicio y fin válidos.'); return false; }
      if(existing){ existing.nombre = nom; existing.pkIni = Math.min(a, b); existing.pkFin = Math.max(a, b); registrarCambio('lugar', 'editado lugar "' + nom + '"'); }
      else { pr.lugares.push({id:uid(), nombre:nom, pkIni:Math.min(a, b), pkFin:Math.max(a, b)}); registrarCambio('lugar', 'añadido lugar "' + nom + '" (' + toPkStr(Math.min(a, b)) + '–' + toPkStr(Math.max(a, b)) + ')'); }
      save(); render();
    },
    existing ? () => { pr.lugares = pr.lugares.filter(x => x.id !== existing.id); registrarCambio('lugar', 'borrado lugar "' + existing.nombre + '"'); save(); render(); } : null
  );
}
