const firstPk = e => { const p = elemPK(e); return !isNaN(p.pu) ? p.pu : (!isNaN(p.ini) ? p.ini : NaN); };

/* ---- extracción de trazos vectoriales de una página (para calibrar/detectar símbolos) ---- */
async function extraerSubpaths(page){
  const ol = await page.getOperatorList(), O = pdfjsLib.OPS;
  let ctm = [1,0,0,1,0,0]; const st = []; let cur = [], cv = 0, seg = 0;
  const out = [];
  const M = (m,n)=>[m[0]*n[0]+m[2]*n[1],m[1]*n[0]+m[3]*n[1],m[0]*n[2]+m[2]*n[3],m[1]*n[2]+m[3]*n[3],m[0]*n[4]+m[2]*n[5]+m[4],m[1]*n[4]+m[3]*n[5]+m[5]];
  const ap = (m,x,y)=>[m[0]*x+m[2]*y+m[4], m[1]*x+m[3]*y+m[5]];
  const flush = () => {
    if(cur.length >= 2){
      let a=1e9,b=1e9,c=-1e9,d=-1e9;
      for(const p of cur){ if(p[0]<a)a=p[0]; if(p[0]>c)c=p[0]; if(p[1]<b)b=p[1]; if(p[1]>d)d=p[1]; }
      out.push({x:(a+c)/2, y:(b+d)/2, w:c-a, h:d-b, cv, seg});
    }
    cur = []; cv = 0; seg = 0;
  };
  const add = (x,y)=>cur.push(ap(ctm, x, y));
  const path = (sub, co) => { let k = 0; for(const sf of sub){
    if(sf===O.moveTo){ flush(); add(co[k],co[k+1]); k+=2; }
    else if(sf===O.lineTo){ add(co[k],co[k+1]); k+=2; seg++; }
    else if(sf===O.curveTo){ add(co[k],co[k+1]); add(co[k+2],co[k+3]); add(co[k+4],co[k+5]); k+=6; cv++; seg++; }
    else if(sf===O.curveTo2){ add(co[k],co[k+1]); add(co[k+2],co[k+3]); k+=4; cv++; seg++; }
    else if(sf===O.curveTo3){ add(co[k],co[k+1]); add(co[k+2],co[k+3]); k+=4; cv++; seg++; }
    else if(sf===O.rectangle){ flush(); const x=co[k],y=co[k+1],w=co[k+2],h=co[k+3]; k+=4; add(x,y);add(x+w,y);add(x+w,y+h);add(x,y+h);add(x,y); seg+=4; }
  } };
  for(let i = 0; i < ol.fnArray.length; i++){
    const fn = ol.fnArray[i], a = ol.argsArray[i];
    if(fn===O.save) st.push(ctm.slice());
    else if(fn===O.restore) ctm = st.pop() || [1,0,0,1,0,0];
    else if(fn===O.transform) ctm = M(ctm, a);
    else if(fn===O.constructPath) path(a[0], a[1]);
    else if(fn===O.moveTo){ flush(); add(a[0],a[1]); }
    else if(fn===O.lineTo){ add(a[0],a[1]); seg++; }
    else if(fn===O.curveTo){ add(a[0],a[1]); add(a[2],a[3]); add(a[4],a[5]); cv++; seg++; }
    else if(fn===O.rectangle){ flush(); add(a[0],a[1]); add(a[0]+a[2],a[1]); add(a[0]+a[2],a[1]+a[3]); add(a[0],a[1]+a[3]); add(a[0],a[1]); seg+=4; }
    else if(fn===O.fill||fn===O.eoFill||fn===O.stroke||fn===O.fillStroke||fn===O.eoFillStroke||fn===O.endPath) flush();
  }
  flush();
  return out;
}
const pkRefDe = t => { const r = t.campos.find(rr => { const c = getCampo(rr.campoId); return c && c.tipo === 'pk'; }); return r ? r.campoId : null; };
const viaRefDe = t => { const r = t.campos.find(rr => { const c = getCampo(rr.campoId); return c && esCampoVia(c); }); return r ? r.campoId : null; };
/* deduce el nº de vía a partir de las etiquetas "VIA N" del plano más cercanas a (x,y) */
function viaDeTexto(txt, x, y, maxD){
  const cands = [];
  txt.forEach(t => {
    const s = String(t.s).trim();
    const m = s.match(/^v[ií]a\s*(\d{1,2})$/i);
    if(m){ cands.push({v:m[1], x:t.x, y:t.y}); return; }
    if(/^v[ií]a$/i.test(s)){
      const nx = txt.find(o => o !== t && Math.abs(o.y - t.y) < 8 && o.x > t.x && o.x - t.x < 45 && /^\d{1,2}$/.test(String(o.s).trim()));
      if(nx) cands.push({v:String(nx.s).trim(), x:t.x, y:t.y});
    }
  });
  let best = '', bd = maxD || 240;
  cands.forEach(cc => { const d = Math.hypot(cc.x - x, cc.y - y); if(d < bd){ bd = d; best = cc.v; } });
  return best;
}
function calibrar(page){
  const pts = [];
  elementosProy().forEach(e => {
    if(!e.plano || e.plano.page !== page || e.plano.x == null) return;
    const k = firstPk(e); if(isNaN(k)) return;
    pts.push({pk:k, x:e.plano.x});
  });
  if(pts.length < 2) return null;
  const ks = pts.map(p => p.pk);
  if(Math.max(...ks) - Math.min(...ks) < 1e-4) return null;
  const n = pts.length; let sx = 0, sy = 0, sxy = 0, sxx = 0;
  pts.forEach(o => { sx += o.pk; sy += o.x; sxy += o.pk * o.x; sxx += o.pk * o.pk; });
  const den = n * sxx - sx * sx; if(Math.abs(den) < 1e-9) return null;
  const m = (n * sxy - sx * sy) / den, c = (sy - m * sx) / n;
  if(!isFinite(m) || Math.abs(m) < 1e-9) return null;
  return {appl:pk => m * pk + c, inv:x => (x - c) / m, n};
}
function posPlano(e, cal, page, defY){
  const p = elemPK(e);
  let y = (e.plano && e.plano.page === page && e.plano.y != null) ? e.plano.y : null;
  let xi = null, xf = null;
  if(cal){
    if(!isNaN(p.ini) && !isNaN(p.fin)){ xi = cal.appl(Math.min(p.ini, p.fin)); xf = cal.appl(Math.max(p.ini, p.fin)); }
    else { const k = firstPk(e); if(!isNaN(k)) xi = cal.appl(k); }
  }
  if(xi == null && e.plano && e.plano.x != null){ xi = e.plano.x; if(e.plano.x2 != null) xf = e.plano.x2; }
  if(xi == null) return null;
  if(y == null) y = defY;
  return {x:xi, x2:(xf != null && Math.abs(xf - xi) > 2) ? xf : null, y};
}

