/* ================= alta por orden hablada / escrita ================= */
/* ---- lectura de PK dictado ----------------------------------------------------------
   El dictado casi nunca devuelve «9+531»: devuelve «pk 9 531», «PK 9,531», «pk 9 más 531»
   o incluso «punto kilométrico nueve más quinientos treinta y uno». Aquí se aceptan todos. */
const NUM_ES = {cero:0, un:1, uno:1, una:1, dos:2, tres:3, cuatro:4, cinco:5, seis:6, siete:7, ocho:8, nueve:9,
  diez:10, once:11, doce:12, trece:13, catorce:14, quince:15, dieciseis:16, 'dieciséis':16, diecisiete:17,
  dieciocho:18, diecinueve:19, veinte:20, veintiuno:21, veintiun:21, 'veintiún':21, veintidos:22, 'veintidós':22,
  veintitres:23, 'veintitrés':23, veinticuatro:24, veinticinco:25, veintiseis:26, 'veintiséis':26, veintisiete:27,
  veintiocho:28, veintinueve:29, treinta:30, cuarenta:40, cincuenta:50, sesenta:60, setenta:70, ochenta:80, noventa:90,
  cien:100, ciento:100, doscientos:200, trescientos:300, cuatrocientos:400, quinientos:500, seiscientos:600,
  setecientos:700, ochocientos:800, novecientos:900, mil:1000};
/* quita la puntuación de alrededor, salvo si la palabra ES el signo (un «,» separador de PK) */
function limpiaPal(w){
  const s = String(w || '').toLowerCase();
  const r = s.replace(/^[¿¡("']+/, '').replace(/[.,;:!?)"']+$/, '');
  return r || s;
}
/* lee un número escrito en palabras al principio de la lista; devuelve {n, k} (k = palabras usadas) */
function numPalabras(ws){
  let tot = 0, cur = 0, k = 0, hubo = false;
  for(; k < ws.length; k++){
    const w = limpiaPal(ws[k]);
    if(w === 'y'){ if(!hubo) break; continue; }
    const n = NUM_ES[w];
    if(n == null) break;
    hubo = true;
    if(n === 1000){ cur = (cur || 1) * 1000; tot += cur; cur = 0; } else cur += n;
  }
  while(k > 0 && limpiaPal(ws[k - 1]) === 'y') k--;   /* no arrastrar una «y» suelta del final */
  return hubo ? {n:tot + cur, k} : null;
}
/* lee un número (dígitos o palabras) al principio de la lista */
function numToken(ws){
  if(!ws.length) return null;
  const d = limpiaPal(ws[0]);
  if(/^\d{1,4}$/.test(d)) return {n:+d, k:1};
  return numPalabras(ws);
}
/* Devuelve todos los PK que aparecen en la frase, en formato «9+531». */
function pksDeOrden(raw){
  /* separar los signos pegados: «9+531» → «9 + 531» */
  const t = String(raw || '').replace(/(\d)\s*([+.,])\s*(\d)/g, '$1 $2 $3');
  const ws = t.split(/\s+/).filter(Boolean);
  const out = [];
  for(let i = 0; i < ws.length; i++){
    const w = limpiaPal(ws[i]);
    const cab = /^(pk|p\.?k|kil[oó]metro|kil[oó]metros)$/.test(w)
      || (w === 'punto' && /^kilom[eé]trico$/.test(limpiaPal(ws[i + 1] || '')));
    if(!cab && !/^\d{1,4}$/.test(w)) continue;
    let j = cab ? i + (w === 'punto' ? 2 : 1) : i;
    const a = numToken(ws.slice(j)); if(!a || a.n > 999) continue;
    j += a.k;
    const s0 = limpiaPal(ws[j] || '');
    let sep = null, b = null;
    if(/^[+.,]$/.test(s0)){ sep = s0; b = numToken(ws.slice(j + 1)); if(b) j += 1 + b.k; }
    else if(/^(m[áa]s|con|coma|punto)$/.test(s0)){   /* «y» no: choca con «vías 1 y 3» */
      sep = /^(coma|punto)$/.test(s0) ? ',' : '+';
      b = numToken(ws.slice(j + 1)); if(b) j += 1 + b.k;
    } else {
      /* «pk 9 300» sin nada entre medias, y el segundo PK de un rango que ya no repite el «pk»
         («del pk 9 300 al 9 800») — pero sólo ahí, para no leer «vías 1 3 5 7» como PK */
      let p0 = i - 1;
      while(p0 >= 0 && /^(el|la|los|las|un|una)$/.test(limpiaPal(ws[p0]))) p0--;
      const prev = limpiaPal(ws[p0] || '');
      if(cab || (out.length && /^(a|al|hasta|y|e)$/.test(prev))){
        const c = numToken(ws.slice(j)); if(c){ sep = '+'; b = c; j += c.k; }
      }
    }
    if(!cab && !b) continue;                  /* un número suelto sin «PK» no es un PK */
    let met;
    if(!b) met = '000';
    else if(sep === ',' || sep === '.') met = String(b.n).slice(0, 3).padEnd(3, '0');   /* 9,5 = 9+500 */
    else met = String(b.n).slice(-3).padStart(3, '0');                                  /* 9 más 53 = 9+053 */
    out.push({pk:a.n + '+' + met, i});
    i = j - 1;
  }
  return out;
}
/* Interpreta una frase tipo «añade una señal en el PK 9+531 lado derecho con nombre E'1»
   y la convierte en {tipoId, codigo, valores}. Sin IA: sólo palabras clave del dominio. */
function parseOrden(txt){
  const raw = String(txt || '').trim();
  if(!raw) return {error:'Escribe o dicta una orden. Ej.: «añade una señal en el PK 9+531 lado derecho con nombre E\'1».'};
  const t = raw.toLowerCase().replace(/\s+/g, ' ');

  const SIN = /** @type {[RegExp, string][]} */ ([
    [/circuito(s)? de v[ií]a|\bc\.?d\.?v\.?\b|\bc\.?v\.?\b/, 't_cdv'],
    [/se[ñn]al(es)?/, 't_senal'],
    [/aguja|desv[ií]o/, 't_aguja'],
    [/baliza/, 't_bal'],
    [/contador( de ejes)?/, 't_ce'],
    [/armario|\bcte\b/, 't_arm'],
    [/cableado|\bcable\b/, 't_cable'],
    [/arqueta/, 't_arq'],
    [/canalizaci[óo]n|canaleta|zanja|cruce\s+bajo\s+v[ií]a|paso\s+de\s+v[ií]a/, 't_canal'],
    [/piquete/, 't_piq'],
    [/\bhito\b/, 't_hito']
  ]);
  let tipoId = null;
  for(const [re, id] of SIN){ if(re.test(t) && getTipo(id)){ tipoId = id; break; } }
  if(!tipoId) for(const tp of state.elementTypes){ if(tp.nombre && t.includes(tp.nombre.toLowerCase())){ tipoId = tp.id; break; } }
  if(!tipoId) return {error:'No he reconocido el tipo. Di: señal, aguja, baliza, circuito de vía, canalización, arqueta, armario, cableado, contador, piquete o hito.'};
  const tipo = getTipo(tipoId);
  const tieneCampo = id => tipo.campos.some(r => r.campoId === id);
  const opcs = id => (getCampo(id) || {}).opciones || [];

  const val = {}, notas = [];

  /* PK — rango o único */
  const pks = pksDeOrden(raw);
  const hayRango = /\b(de(?:sde|l)?|entre)\b/.test(t) && /\b(a|al|hasta)\b/.test(t);
  let pkIni = '', pkFin = '', pkUno = '';
  if(pks.length >= 2 && (hayRango || tieneCampo('f_pkini'))){ pkIni = pks[0].pk; pkFin = pks[1].pk; }
  else if(pks.length) pkUno = pks[0].pk;
  if(tieneCampo('f_pkini') && tieneCampo('f_pkfin')){
    if(pkIni && pkFin){ val.f_pkini = pkIni; val.f_pkfin = pkFin; }
    else if(pkUno){ val.f_pkini = pkUno; val.f_pkfin = pkUno; notas.push('sólo un PK: inicio = fin'); }
  } else if(tieneCampo('f_pk') && (pkUno || pkIni)){
    val.f_pk = pkUno || pkIni;
  }
  if(!pks.length) notas.push('sin PK: di «PK 9+531», «PK 9 531» o «PK nueve más quinientos treinta y uno»');

  /* vía */
  const mv = t.match(/\bv[ií]a\s+(\d{1,2})\b/) || (() => {
    const m = t.match(/\bv[ií]a\s+([a-záéíóúñ]+(?:\s+[a-záéíóúñ]+)?)/);
    if(!m) return null;
    const n = numPalabras(m[1].split(/\s+/));
    return n && n.n <= 99 ? [m[0], String(n.n)] : null;
  })();
  if(mv && tieneCampo('f_via')) val.f_via = mv[1];

  /* lado */
  let lado = '';
  if(/lado\s+derech|a la derecha|(?:^|\s)derech/.test(t)) lado = 'Lado derecho (abajo)';
  else if(/lado\s+izquierd|a la izquierda|(?:^|\s)izquierd/.test(t)) lado = 'Lado izquierdo (arriba)';
  else if(/\bentrev[ií]as\b/.test(t)) lado = 'Entrevías';
  else if(/\barriba\b/.test(t)) lado = 'Lado izquierdo (arriba)';
  else if(/\babajo\b/.test(t)) lado = 'Lado derecho (abajo)';
  else if(/cruce\s+bajo\s+v[ií]a|paso\s+de\s+v[ií]a/.test(t)) lado = 'Cruce bajo vía';
  if(lado === 'Cruce bajo vía'){
    if(tieneCampo('f_tcanal')) val.f_tcanal = 'Cruce bajo vía';
    else if(tieneCampo('f_lado')) val.f_lado = 'Cruce bajo vía';
    if(tieneCampo('f_cruce_vias')){
      const dg = (t.match(/(?:v[ií]as?|atravies[ae]|cruza)\s+((?:\d{1,2}[\s,yael]+)*\d{1,2})/) || [])[1];
      const ns = dg && dg.match(/\d{1,2}/g);
      if(ns && ns.length) val.f_cruce_vias = [...new Set(ns)].join(',');
    }
  } else if(lado && tieneCampo('f_lado') && opcs('f_lado').includes(lado)) val.f_lado = lado;

  /* estado de montaje */
  if(tieneCampo('f_estado')) for(const o of opcs('f_estado')){
    const stem = o.toLowerCase().replace(/[oa]s?$/, '');
    if(stem.length > 3 && t.includes(stem)){ val.f_estado = o; break; }
  }

  /* longitud del cruce: «… con longitud 18», «… de 18 metros» */
  if(tieneCampo('f_cruce_long')){
    const ml = t.match(/(?:longitud|largo|ancho)\s*(?:de\s*|del\s*)?(\d{1,4})/) || t.match(/(\d{1,4})\s*(?:m\b|metros?)/);
    if(ml) val.f_cruce_long = ml[1];
  }

  /* resto de desplegables (tipo de arqueta, tipo de cable, disposición…): se busca la opción literal */
  const YA = ['f_lado', 'f_estado', 'f_tsenal', 'f_tcanal'];
  tipo.campos.forEach(r => {
    const c = getCampo(r.campoId);
    if(!c || c.tipo !== 'select' || val[c.id] || YA.includes(c.id)) return;
    for(const o of (c.opciones || [])){
      const lo = String(o).toLowerCase();
      if(lo.length > 2 && t.includes(lo)){ val[c.id] = o; break; }
    }
  });

  /* estación / lugar: «… en la estación de CATOIRA» */
  const me = raw.match(/\b(?:en\s+)?(?:la\s+)?estaci[óo]n\s+(?:de\s+|del\s+)?([A-Za-zÁÉÍÓÚÜÑáéíóúüñ][\wÁÉÍÓÚÜÑáéíóúüñ.\- ]{1,40}?)(?=\s+(?:en|con|de|del|v[ií]a|lado|y)\b|[,;.]|$)/i);
  if(me && tieneCampo('f_est')) val.f_est = me[1].trim();

  /* código / nombre — puede ser de varias palabras (BAL E1, CV A3); se corta al llegar a otra instrucción */
  let codigo = '';
  const mc = raw.match(/(?:con\s+nombre|nombre|llamad[oa]|que\s+se\s+llame|c[óo]digo|marcad[oa]\s+como)\s+(.+)$/i);
  if(mc){
    codigo = mc[1]
      .split(/\s+(?:del?\b|desde\b|hasta\b|al?\b|en\s+(?:el\s+|la\s+)?(?:p\.?k\.?|punto\s+kilom[ée]trico|kil[oó]metro|estaci[óo]n)|p\.?k\.?\s|v[ií]a\b|lado\b|instalad|pendiente|verificad|en\s+ejecuci|con\s+incidenci|entrev[ií]as|arriba\b|abajo\b|a\s+la\s+derecha|a\s+la\s+izquierda)/i)[0]
      .replace(/\s*\d{1,3}\s*[+.,]\s*\d{1,3}.*$/, '')
      .trim().replace(/[.,;]+$/, '').replace(/[´`]/g, "'");
  }

  /* tipo de señal, por el código o por palabra */
  if(tipoId === 't_senal' && tieneCampo('f_tsenal')){
    let ts = '';
    if(/^e['’]/i.test(codigo)) ts = 'Avanzada';
    else if(/^e\d/i.test(codigo)) ts = 'Entrada';
    else if(/^i?s\d/i.test(codigo)) ts = 'Salida';
    else if(/^r\d/i.test(codigo)) ts = 'Retroceso';
    if(!ts) for(const o of opcs('f_tsenal')){ if(t.includes(o.toLowerCase())){ ts = o; break; } }
    if(ts) val.f_tsenal = ts;
  }

  const faltan = tipo.campos.filter(r => r.obligatorio && !val[r.campoId] && !r.regla)
    .map(r => (getCampo(r.campoId) || {}).etiqueta).filter(Boolean);
  return {tipoId, tipo, codigo, valores:val, notas, faltan};
}
function crearDesdeOrden(r, textoOrden){
  if(soloLectura()) return null;
  const nid = uid();
  state.elementos.push({id:nid, proyectoId:state.proyectoActivo, tipoId:r.tipoId, codigo:r.codigo || '',
    valores:r.valores, hist:[], plano:null, creado:Date.now(), modificado:Date.now()});
  registrarCambio('alta (voz)', (r.codigo || r.tipo.nombre) + ' (' + r.tipo.nombre + ') — «' + textoOrden + '»', nid);
  save(); render();
  return nid;
}
function ordenModal(){
  if(soloLectura()){ alert('Estás viendo el proyecto a una fecha pasada (solo lectura).'); return; }
  const inp = el('input', {placeholder:"añade una señal en el PK 9+531 lado derecho con nombre E'1", style:'font-size:14px'});
  const prev = el('div', {style:'margin-top:12px;font-size:13px;min-height:46px'});
  const refresca = () => {
    prev.innerHTML = '';
    if(!inp.value.trim()) return;
    const r = parseOrden(inp.value);
    if(r.error){ prev.appendChild(el('div', {style:'color:var(--amb)'}, r.error)); return; }
    const campos = Object.keys(r.valores).map(k => (getCampo(k) || {}).etiqueta + ': ' + r.valores[k]);
    const pkTxt = r.valores.f_pk ? r.valores.f_pk
      : (r.valores.f_pkini ? r.valores.f_pkini + ' → ' + (r.valores.f_pkfin || r.valores.f_pkini) : '');
    prev.appendChild(el('div', null,
      el('div', {style:'color:var(--tx)'}, 'Voy a crear: ', el('b', null, r.tipo.nombre),
        r.codigo ? el('span', null, ' «', el('b', null, r.codigo), '»') : ''),
      el('div', {style:'margin-top:4px;color:' + (pkTxt ? 'var(--ok,#33c07d)' : 'var(--amb)')},
        pkTxt ? 'PK entendido: ' + pkTxt : 'PK: no lo he entendido'),
      el('div', {style:'color:var(--tx3);margin-top:4px'}, campos.length ? campos.join('  ·  ') : 'sin datos reconocidos'),
      (r.faltan && r.faltan.length) ? el('div', {style:'color:var(--amb);margin-top:4px'}, 'Faltará por rellenar: ' + r.faltan.join(', ')) : '',
      (r.notas && r.notas.length) ? el('div', {style:'color:var(--tx3);margin-top:2px'}, r.notas.join('  ·  ')) : ''
    ));
  };
  inp.addEventListener('input', refresca);

  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  let recog = null;
  const micBtn = SR ? el('button', {class:'btn', type:'button', style:'white-space:nowrap'}, '🎤 Dictar') : null;
  if(micBtn) micBtn.addEventListener('click', () => {
    if(recog){ recog.stop(); return; }
    recog = new SR(); recog.lang = 'es-ES'; recog.interimResults = true; recog.continuous = false;
    micBtn.textContent = '● Escuchando…';
    recog.onresult = e => { let s = ''; for(let i = 0; i < e.results.length; i++) s += e.results[i][0].transcript; inp.value = s; refresca(); };
    recog.onerror = e => { alert('No se pudo usar el micrófono (' + e.error + '). Escribe la orden.'); };
    recog.onend = () => { micBtn.textContent = '🎤 Dictar'; recog = null; };
    try{ recog.start(); }catch(e){ recog = null; micBtn.textContent = '🎤 Dictar'; }
  });

  openModal('Orden por voz o texto',
    el('div', null,
      el('div', {style:'display:flex;gap:8px;align-items:center'}, inp, micBtn || ''),
      el('div', {class:'hint', style:'margin-top:8px'},
        el('div', null, 'Orden: ', el('b', null, 'tipo'), ' + ', el('b', null, 'PK'), ' + lado / vía / estado + «con nombre …». Al pulsar Guardar se crea (deshacible con ⟲).'),
        el('div', {style:'margin-top:6px'}, 'El ', el('b', null, 'PK'), ' se entiende dicho de cualquiera de estas formas:'),
        el('ul', {style:'margin:4px 0 0 16px;padding:0'},
          el('li', null, '«PK 9+531», «PK 9,531», «PK 9.531»'),
          el('li', null, '«PK 9 531» — sin decir nada entre medias'),
          el('li', null, '«PK 9 más 531» / «kilómetro 9 con 531»'),
          el('li', null, '«PK nueve más quinientos treinta y uno»'),
          el('li', null, 'tramo: «del PK 9+300 al 9+600»'),
          el('li', null, '«PK 9 coma 5» = 9+500 · «PK 9 más 53» = 9+053')),
        el('div', {style:'margin-top:6px'}, 'Ejemplo completo: «añade una señal en el PK 9+531 lado derecho vía 1 con nombre E\'1».'),
        SR ? '' : el('div', {style:'margin-top:6px;color:var(--amb)'}, 'El micrófono no está disponible en este navegador — escribe la orden.')),
      prev
    ),
    () => {
      const r = parseOrden(inp.value);
      if(r.error){ alert(r.error); return false; }
      crearDesdeOrden(r, inp.value.trim());
    }
  );
  setTimeout(() => inp.focus(), 30);
}
