  tb2.appendChild(el('span', {class:'spacer'}));
  tb2.appendChild(el('label', {style:'display:flex;align-items:center;gap:6px;font-size:12px'},
    el('input', {type:'checkbox', ...(esqAdd.on ? {checked:'checked'} : {}), onchange:e => { esqAdd.on = e.target.checked; esqColocar = null; esqCalib = false; render(); }}), 'Modo añadir'));
  tb2.appendChild(el('select', {style:'width:auto', onchange:e => esqAdd.tipoId = e.target.value},
    ...state.elementTypes.map(t => el('option', {value:t.id, ...(t.id === esqAdd.tipoId ? {selected:'selected'} : {})}, t.nombre))));
  cont.appendChild(tb2);

  const firmas = proyActivo().firmas || [];
  const tb3 = el('div', {class:'pdf-toolbar', style:'margin-top:8px'});
  tb3.appendChild(el('label', {style:'display:flex;align-items:center;gap:6px;font-size:12px'},
    el('input', {type:'checkbox', ...(esqCalib ? {checked:'checked'} : {}), onchange:e => { esqCalib = e.target.checked; esqAdd.on = false; esqColocar = null; render(); }}), 'Calibrar símbolos'));
  tb3.appendChild(el('button', {class:'btn sm', onclick:() => configFirmas()}, 'Símbolos (' + firmas.length + ')'));
  tb3.appendChild(el('button', {class:'btn sm', ...(firmas.length ? {} : {disabled:'disabled'}), onclick:() => detectarSimbolos(false)}, 'Detectar en esta hoja'));
  tb3.appendChild(el('button', {class:'btn sm', ...(firmas.length ? {} : {disabled:'disabled'}), onclick:() => detectarSimbolos(true)}, 'Detectar en todas'));
  tb3.appendChild(el('span', {class:'spacer'}));
  tb3.appendChild(el('span', {style:'color:var(--tx3);font-size:12px'}, 'Calibra un ejemplo de cada símbolo y "Detectar" busca las copias'));
  cont.appendChild(tb3);
  if(esqCalib) cont.appendChild(el('p', {class:'hint', style:'color:var(--amb)'}, 'Haz clic justo encima de un símbolo (semáforo, aguja, baliza…) para capturar su firma.'));

  const cal = calibrar(esqPage);
  cont.appendChild(el('p', {class:'hint'}, cal
    ? 'PK calibrado con ' + cal.n + ' puntos: al cambiar el PK de un elemento se recoloca en el plano.'
    : 'Aún no se puede calibrar el PK (hacen falta 2+ elementos con posición y PK). Coloca elementos con "Modo añadir" o desde los chips de abajo.'));
  if(esqAdd.on) cont.appendChild(el('p', {class:'hint', style:'color:var(--amb)'}, 'Haz clic sobre el plano para añadir un elemento en ese punto.'));
  if(esqColocar){ const ec = state.elementos.find(x => x.id === esqColocar); cont.appendChild(el('p', {class:'hint', style:'color:var(--amb)'}, 'Haz clic en el plano para situar ' + (ec ? (ec.codigo || 'el elemento') : '') + '.')); }

  if(detSimb) cont.appendChild(panelDetSimb());

  const holder = el('div', {class:'esq-wrap', style:'position:relative'});
  holder.appendChild(el('canvas', {id:'esqPdf', style:'display:block'}));
  holder.appendChild(el('div', {id:'esqLayer'}));
  holder.addEventListener('wheel', ev => {
    ev.preventDefault();
    const r = holder.getBoundingClientRect();
    const fx = (holder.scrollLeft + ev.clientX - r.left) / Math.max(1, holder.scrollWidth);
    const fy = (holder.scrollTop + ev.clientY - r.top) / Math.max(1, holder.scrollHeight);
    esqPdfScale = Math.max(0.3, Math.min(12, (esqPdfScale || 1) * (ev.deltaY < 0 ? 1.2 : 1 / 1.2)));
    esqWheelPend = {fx, fy, pdf:true};
    reRenderLento();
  }, {passive:false});
  cont.appendChild(holder);

  const sinUb = els.filter(e => !(e.plano && e.plano.x != null) && isNaN(firstPk(e)));
  const trasCal = els.filter(e => !posPlano(e, cal, esqPage, 0));
  const tray = [...new Set(sinUb.concat(trasCal))];
